mapper.select:
SELECT policy_no AS policyNo, commission_base AS commissionBase, status AS status, create_time AS createTime,
-- 🌟 核心魔法 1：收益聚合合并
-- 直推件：把该用户在这笔订单里所有口袋的钱加起来 (sales_ratio + CASE WHEN team_user_id = #{userId} THEN team_ratio ELSE 0 END + CASE WHEN project_user_id = #{userId} THEN project_ratio ELSE 0 END) AS ratio,
(sales_amount + CASE WHEN team_user_id = #{userId} THEN team_amount ELSE 0 END + CASE WHEN project_user_id = #{userId} THEN project_amount ELSE 0 END) AS amount
-- 团队件：只看团队口袋的钱 team_ratio AS ratio, team_amount AS amount
-- 分红件：只看分红口袋的钱 project_ratio AS ratio, project_amount AS amount
FROM biz_commission_record WHERE status = 0 AND del_flag = '0'
-- 🌟 核心魔法 2：身份互斥过滤 (绝对防止同一个单子出现在多个 Tab)
-- 只要是我开的单，全算直推 AND sales_user_id = #{userId}
-- 必须是我拿了团队奖，且不是我亲自开的单 AND team_user_id = #{userId} AND sales_user_id != #{userId}
-- 必须是我拿了分红，且不是我开的单，也不是我直属徒弟开的单 AND project_user_id = #{userId} AND team_user_id != #{userId} AND sales_user_id != #{userId}
AND DATE_FORMAT(create_time, '%Y-%m') = #{bo.queryMonth}
ORDER BY create_time DESC
